ssed forms</div>`;html+=`<div style=\"margin-top:8px\">Maximum recoverable: ≤ <span class=\"highlight\">${maxRecoverable.toLocaleString()}</span> (${pctRecoverable.toFixed(2)}%)</div>`;html+=`<div>Minimum lost: ≥ <span class=\"warn\">${minLost.toLocaleString()}</span> (${pctLost.toFixed(2)}%)</div>`;html+=`<div style=\"margin-top:8px\">Lost ≥ Recoverable? <span class=\"${minLost>=maxRecoverable?'highlight':'warn'}\">${minLost>=maxRecoverable?'✓ YES':'✗ NO (need M < L and A ≥ 2)'}</span></div>`;html+=`<div class=\"bar-container\"><span class=\"bar-label\">Recoverable</span><div class=\"bar\" style=\"width:${Math.max(1,pctRecoverable)}%;background:#50fa7b\"></div><span>${pctRecoverable.toFixed(1)}%</span></div>`;html+=`<div class=\"bar-container\"><span class=\"bar-label\">Lost forever</span><div class=\"bar\" style=\"width:${Math.max(1,pctLost)}%;background:#ff5555\"></div><span>${pctLost.toFixed(1)}%</span></div>`;document.getElementById('compResult').innerHTML=html}function updatePeriodic(){const A=Math.max(1,parseInt(document.getElementById('perA').value)||1);const L=Math.max(1,parseInt(document.getElementById('perL').value)||1);const libSize=Math.pow(A,L);let html=`<div>Library: A<sup>${L}</sup> = ${libSize>1e15?'10<sup>'+Math.log10(libSize).toFixed(1)+'</sup>':libSize.toLocaleString()} volumes</div>`;html+=`<div style=\"margin-top:8px\">Periodic subsets (p divides ${L}):</div>`;let found=false;for(let p=1;p<=L;p++){if(L%p!==0)continue;found=true;const count=Math.pow(A,p);const frac=count/libSize;const pctW=Math.max(1,Math.log10(count+1)/Math.log10(libSize+1)*100);html+=`<div class=\"bar-container\"><span class=\"bar-label\">p=${p}: A<sup>${p}</sup>=${count>1e12?'10^'+Math.log10(count).toFixed(1):count.toLocaleString()}</span><div class=\"bar\" style=\"width:${pctW}%;background:hsl(${p*30},70%,50%)\"></div><span>${(frac*100).toFixed(frac<0.01?4:2)}%</span></div>`}document.getElementById('perResult').innerHTML=html}['catA','catL','catD'].forEach(id=>document.getEl