      "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>Counterpoint Quiver</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;min-height:100vh;padding:20px}h1{font-size:1.6em;margin-bottom:4px;color:#fff}h2{font-size:1em;color:#888;margin-bottom:20px;font-weight:normal}.container{position:relative;width:640px;height:640px}canvas{position:absolute;top:0;left:0}.legend{display:flex;gap:20px;margin-top:16px;font-size:.85em}.legend-item{display:flex;align-items:center;gap:6px}.dot{width:12px;height:12px;border-radius:50%}.info{margin-top:16px;background:#14142a;border:1px solid #333;border-radius:8px;padding:16px;max-width:640px;width:100%}.info h3{color:#ffcc00;margin-bottom:8px;font-size:1em}.info p{font-size:.9em;line-height:1.5;color:#bbb}.stats{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:16px;max-width:640px;width:100%}.stat{background:#14142a;border:1px solid #333;border-radius:8px;padding:12px;text-align:center}.stat .num{font-size:2em;font-weight:bold;color:#ffcc00}.stat .label{font-size:.8em;color:#888;margin-top:4px}#tooltip{position:absolute;background:rgba(20,20,42,.95);border:1px solid #ffcc00;border-radius:6px;padding:8px 12px;font-size:.85em;pointer-events:none;display:none;z-index:10;color:#fff}</style></head><body><h1>The Counterpoint Quiver</h1><h2>First-Species Counterpoint over ℤ/12ℤ</h2><div class=\"container\"><canvas id=\"c\" width=\"640\" height=\"640\"></canvas><div id=\"tooltip\"></div></div><div class=\"legend\"><div class=\"legend-item\"><div class=\"dot\" style=\"background:#ff4444\"></div>Perfect consonance</div><div class=\"legend-item\"><div class=\"dot\" style=\"background:#44aaff\"></div>Imperfect consonance</div><div class=\"legend-item\"><div class=\"dot\" style=\"background:rgba(255,204,0,.3)\"></div>Edge (width ∝ count)</div></div><div class=\"stats\"><div class=\"stat\"><div class=\"num\">410</div><div class=\"label\">Total Edges</div></div><div class=\"stat\"><div class=\"num\">6</div><div class=\"label\">Consonant Intervals</div></div><div class=\"stat\"><div class=\"num\">1 : 12</div><div class=\"label\">Perfect : Imperfect Self-Loops</div></div><div class=\"stat\"><div class=\"num\">61 vs 72</div><div class=\"label\">Incoming to P vs I</div></div></div><div class=\"info\"><h3>Bottleneck Theorem</h3><p>Perfect consonances (unison, fifth) admit exactly <strong>1 self-loop</strong> — the identity. Imperfect consonances (thirds, sixths) admit <strong>12 self-loops</strong>. This 12:1 ratio is the categorical signature of the prohibition on parallel fifths and octaves. Hover over nodes to see details.</p></div><script>const W=640,H=640,cx=W/2,cy=H/2,R=220;const intervals=[{id:0,name:'Unison/Oct',short:'P1/P8',type:'perfect',sem:0},{id:3,name:'Minor 3rd',short:'m3',type:'imperfect',sem:3},{id:4,name:'Major 3rd',short:'M3',type:'imperfect',sem:4},{id:7,name:'Perfect 5th',short:'P5',type:'perfect',sem:7},{id:8,name:'Minor 6th',short:'m6',type:'imperfect',sem:8},{id:9,name:'Major 6th',short:'M6',type:'imperfect',sem:9}];const N=intervals.length;const edges=[[1,12,12,12,12,12],[12,12,12,12,12,12],[12,12,12,12,12,12],[12,12,12,1,12,12],[12,12,12,12,12,12],[12,12,12,12,12,12]];intervals.forEach((v,i)=>{const a=-Math.PI/2+i*(2*Math.PI/N);v.x=cx+R*Math.cos(a);v.y=cy+R*Math.sin(a)});const canvas=document.getElementById('c');const ctx=canvas.getContext('2d');const tooltip=document.getElementById('tooltip');let hovered=-1;function draw(){ctx.clearRect(0,0,W,H);for(let i=0;i<N;i++){for(let j=0;j<N;j++){if(i===j)continue;const count=edges[i][j];const a=intervals[i],b=intervals[j];const dx=b.x-a.x,dy=b.y-a.y;const len=Math.sqrt(dx*dx+dy*dy);const nx=-dy/len,ny=dx/len;const off=8;const mx=(a.x+b.x)/2+nx*off*1.5;const my=(a.y+b.y)/2+ny*off*1.5;ctx.beginPath();ctx.moveTo(a.x+nx*off,a.y+ny*off);ctx.quadraticCurveTo(mx,my,b.x+nx*off,b.y+ny*off);const isToPerf=intervals[j].type==='perfect';ctx.strokeStyle=isToPerf?'rgba(255,68,68,0.2)':'rgba(68,170,255,0.15)';ctx.lineWidth=count===12?2:0.8;ctx.stroke();const t=0.7;const ex=(1-t)*(1-t)*(a.x+nx*off)+2*(1-t)*t*mx+t*t*(b.x+nx*off);const ey=(1-t)*(1-t)*(a.y+ny*off)+2*(1-t)*t*my+t*t*(b.y+ny*off);const tax=2*(1-t)*((mx)-(a.x+nx*off))+2*t*((b.x+nx*off)-(mx));const tay=2*(1-t)*((my)-(a.y+ny*off))+2*t*((b.y+ny*off)-(my));const al=Math.atan2(tay,tax);ctx.beginPath();ctx.moveTo(ex,ey);ctx.lineTo(ex-8*Math.cos(al-0.3),ey-8*Math.sin(al-0.3));ctx.moveTo(ex,ey);ctx.lineTo(ex-8*Math.cos(al+0.3),ey-8*Math.sin(al+0.3));ctx.strokeStyle=isToPerf?'rgba(255,68,68,0.35)':'rgba(68,170,255,0.25)';ctx.lineWidth=1.5;ctx.stroke()}}for(let i=0;i<N;i++){const v=intervals[i];const isPerf=v.type==='perfect';const selfLoops=isPerf?1:12;const r=isPerf?28:22;ctx.beginPath();ctx.arc(v.x,v.y,r,0,2*Math.PI);ctx.fillStyle=i===hovered?(isPerf?'rgba(255,68,68,0.4)':'rgba(68,170,255,0.3)'):(isPerf?'rgba(255,68,68,0.15)':'rgba(68,170,255,0.1)');ctx.fill();ctx.strokeStyle=isPerf?'#ff4444':'#44aaff';ctx.lineWidth=isPerf?2.5:1.5;ctx.stroke();ctx.fillStyle='#fff';ctx.font='bold 11px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(v.short,v.x,v.y-6);ctx.font='9px system-ui';ctx.fillStyle='#aaa';ctx.fillText(selfLoops+' loop'+(selfLoops>1?'s':''),v.x,v.y+8);const loopA=-Math.PI/2+(2*Math.PI/N)*intervals.indexOf(v);const lr=18;const lcx=v.x+Math.cos(loopA)*(r+lr);const lcy=v.y+Math.sin(loopA)*(r+lr);ctx.beginPath();ctx.arc(lcx,lcy,lr,0,2*Math.PI);ctx.strokeStyle=isPerf?'rgba(255,68,68,0.3)':'rgba(68,170,255,0.15)';ctx.lineWidth=isPerf?1:selfLoops*0.3;ctx.stroke()}}canvas.addEventListener('mousemove',e=>{const rect=canvas.getBoundingClientRect();const mx=e.clientX-rect.left;const my=e.clientY-rect.top;let found=-1;for(let i=0;i<N;i++){const dx=mx-intervals[i].x,dy=my-intervals[i].y;if(dx*dx+dy*dy<900)found=i}if(found!==hovered){hovered=found;draw();if(found>=0){const v=intervals[found];const incoming=edges.reduce((s,row)=>s+row[found],0);const outgoing=edges[found].reduce((a,b)=>a+b,0);const selfL=v.type==='perfect'?1:12;tooltip.innerHTML=`<strong>${v.name}</strong> (${v.sem} semitones)<br>Type: ${v.type}<br>Self-loops: ${selfL}<br>Incoming: ${incoming}<br>Outgoing: ${outgoing}`;tooltip.style.display='block';tooltip.style.left=(e.clientX-canvas.getBoundingClientRect().left+15)+'px';tooltip.style.top=(e.clientY-canvas.getBoundingClientRect().top-10)+'px'}else{tooltip.style.display='none'}}});draw()</script></body></html>"
