0+80*intensity):Math.round(60+180*intensity);const bg=`rgb(${r},${g},${b})`;const cell=addCell('',`<b>${c}</b>`,{background:bg});cell.addEventListener('mouseenter',()=>{document.getElementById('info').innerHTML=`<b>${intervals[i].name}</b> (${intervals[i].id}) → <b>${intervals[j].name}</b> (${intervals[j].id}): <b>${c}</b> permitted voice leadings` +(c<12?` <span style='color:#f88'>(${12-c} eliminated by parallel-motion rule)</span>`:'')}); grid.appendChild(cell)}grid.appendChild(addCell('sum-cell',`<b>${rowSum}</b>`))}grid.appendChild(addCell('header','Σ in'));let grandTotal=0;for(let j=0;j<n;j++){let colSum=0;for(let i=0;i<n;i++)colSum+=homCount(i,j,constrained);grandTotal+=colSum;grid.appendChild(addCell('sum-cell',`<b>${colSum}</b>`))}grid.appendChild(addCell('sum-cell',`<b>${grandTotal}</b>`,{background:'rgba(100,140,255,0.1)'}));const elim=constrained?432-grandTotal:0;document.getElementById('statTotal').textContent=grandTotal;document.getElementById('statElim').textContent=elim;const pIn=constrained?61:72;const iIn=constrained?72:72;document.getElementById('statPerfIn').textContent=pIn;document.getElementById('statImpIn').textContent=iIn}buildGrid()</script></body></html>"
