      "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>Voice-Swap Asymmetry</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;padding:20px;min-height:100vh}h1{font-size:1.5em;color:#fff;margin-bottom:4px}h2{font-size:.95em;color:#888;font-weight:normal;margin-bottom:20px}.wrap{display:flex;gap:40px;align-items:flex-start;flex-wrap:wrap;justify-content:center}canvas{border-radius:12px;background:#0d0d24}.panel{background:#14142a;border:1px solid #333;border-radius:8px;padding:16px;max-width:320px}.panel h3{color:#ffcc00;margin-bottom:10px;font-size:1em}.panel table{width:100%;border-collapse:collapse;font-size:.85em}.panel th,.panel td{padding:6px 8px;text-align:center;border-bottom:1px solid #222}.panel th{color:#888}.cons{color:#44ff88}.disc{color:#ff4444;font-weight:bold}.note{margin-top:12px;font-size:.85em;color:#bbb;line-height:1.5}</style></head><body><h1>Voice-Swap Asymmetry</h1><h2>The involution σ: i ↦ −i on ℤ/12ℤ</h2><div class=\"wrap\"><canvas id=\"c\" width=\"420\" height=\"420\"></canvas><div class=\"panel\"><h3>σ Maps Consonances To…</h3><table><tr><th>Interval</th><th>i</th><th>σ(i)=−i</th><th>Status</th></tr><tr><td>Unison</td><td>0</td><td>0</td><td class=\"cons\">✓ Consonant</td></tr><tr><td>Minor 3rd</td><td>3</td><td>9</td><td class=\"cons\">✓ Consonant</td></tr><tr><td>Major 3rd</td><td>4</td><td>8</td><td class=\"cons\">✓ Consonant</td></tr><tr><td>Perfect 5th</td><td>7</td><td>5</td><td class=\"disc\">✗ DISSONANT</td></tr><tr><td>Minor 6th</td><td>8</td><td>4</td><td class=\"cons\">✓ Consonant</td></tr><tr><td>Major 6th</td><td>9</td><td>3</td><td class=\"cons\">✓ Consonant</td></tr></table><p class=\"note\">The perfect fifth (7) maps to the perfect fourth (5), which is <strong style=\"color:#ff4444\">not consonant</strong> in first-species counterpoint. This single failure proves that the consonant set is not invariant under voice exchange — the bass voice occupies a privileged, asymmetric position.</p></div></div><script>const c=document.getElementById('c'),ctx=c.getContext('2d'),W=420,H=420,cx=W/2,cy=H/2,R=160;const consonant=new Set([0,3,4,7,8,9]);const names=['C','C♯','D','E♭','E','F','F♯','G','A♭','A','B♭','B'];const intNames={0:'P1',1:'m2',2:'M2',3:'m3',4:'M3',5:'P4',6:'TT',7:'P5',8:'m6',9:'M6',10:'m7',11:'M7'};let anim=0;function draw(){ctx.clearRect(0,0,W,H);ctx.strokeStyle='#222';ctx.lineWidth=1;ctx.beginPath();ctx.arc(cx,cy,R,0,2*Math.PI);ctx.stroke();for(let i=0;i<12;i++){const a=-Math.PI/2+i*(2*Math.PI/12);const x=cx+R*Math.cos(a),y=cy+R*Math.sin(a);const isCons=consonant.has(i);const neg=(12-i)%12;const negCons=consonant.has(neg);if(isCons){const na=-Math.PI/2+neg*(2*Math.PI/12);const nx=cx+R*Math.cos(na),ny=cy+R*Math.sin(na);const t=Math.min(1,(anim-i*5)/30);if(t>0){const broken=!negCons;ctx.beginPath();ctx.moveTo(x,y);const mx=cx+(broken?0.3:0.15)*(x+nx-2*cx)/2;const my=cy+(broken?0.3:0.15)*(y+ny-2*cy)/2;ctx.quadraticCurveTo(cx+mx*0.3,cy+my*0.3,x+(nx-x)*t,y+(ny-y)*t);ctx.strokeStyle=broken?'rgba(255,68,68,0.7)':'rgba(68,255,136,0.3)';ctx.lineWidth=broken?3:1.5;ctx.setLineDash(broken?[6,4]:[]);ctx.stroke();ctx.setLineDash([]);if(broken&&t>=1){ctx.font='bold 11px system-ui';ctx.fillStyle='#ff4444';ctx.textAlign='center';const lx=(x+nx)/2-15,ly=(y+ny)/2;ctx.fillText('✗',lx,ly)}}}const r2=isCons?14:8;ctx.beginPath();ctx.arc(x,y,r2,0,2*Math.PI);if(isCons){ctx.fillStyle=i===7?'rgba(255,204,0,0.3)':'rgba(68,255,136,0.15)';ctx.fill();ctx.strokeStyle=i===7?'#ffcc00':'#44ff88';ctx.lineWidth=2}else if(i===5){ctx.fillStyle='rgba(255,68,68,0.2)';ctx.fill();ctx.strokeStyle='#ff4444';ctx.lineWidth=2}else{ctx.fillStyle='rgba(100,100,100,0.1)';ctx.fill();ctx.strokeStyle='#444';ctx.lineWidth=1}ctx.stroke();ctx.fillStyle=isCons?'#fff':(i===5?'#ff8888':'#666');ctx.font=(isCons||i===5)?'bold 10px system-ui':'9px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(intNames[i],x,y);const lx=cx+(R+28)*Math.cos(a),ly=cy+(R+28)*Math.sin(a);ctx.fillStyle=isCons?'#aaa':'#444';ctx.font='9px system-ui';ctx.fillText(names[i],lx,ly)}ctx.fillStyle='#fff';ctx.font='bold 13px system-ui';ctx.textAlign='center';ctx.fillText('σ: i ↦ −i',cx,cy-12);ctx.fillStyle='#888';ctx.font='11px system-ui';ctx.fillText('(mod 12)',cx,cy+6);anim+=1.5;requestAnimationFrame(draw)}draw()</script></body></html>"
