    {
      "title": "Self-Reference Impossibility",
      "description": "Visualization of the diagonal argument showing why the Library cannot contain its own catalog — the number of evaluation functions always exceeds the number of volumes.",
      "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>Self-Reference Impossibility</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;padding:20px;min-height:100vh}h1{font-size:1.5em;color:#7eb8ff;margin-bottom:4px}h2{font-size:.95em;color:#888;font-weight:normal;margin-bottom:20px}.main{max-width:900px;width:100%}.card{background:#12122a;border:1px solid #2a2a4a;border-radius:12px;padding:20px;margin-bottom:20px}.row{display:flex;gap:15px;flex-wrap:wrap;margin-bottom:15px}.slider-group{flex:1;min-width:150px}.slider-group label{display:block;font-size:.85em;color:#aaa;margin-bottom:4px}.slider-group input[type=range]{width:100%;accent-color:#7eb8ff}.slider-group .val{color:#ffcc00;font-weight:bold}canvas{width:100%;border-radius:8px}table{width:100%;border-collapse:collapse;font-size:.82em;margin-top:8px}th{color:#7eb8ff;text-align:left;padding:6px;border-bottom:2px solid #3a3a5a}td{padding:5px 6px;border-bottom:1px solid #1a1a3a}.diag{background:#3a1a1a;color:#ff6666;font-weight:bold}.info{background:#1a1a3a;border-radius:8px;padding:15px;font-size:.9em;line-height:1.7;margin-top:10px}.info b{color:#7eb8ff}.highlight{color:#ffcc00}</style></head><body><h1>🚫 The Diagonal Argument</h1><h2>Why the Library cannot contain its own complete catalog</h2><div class=\"main\"><div class=\"card\"><div class=\"row\"><div class=\"slider-group\"><label>Alphabet A: <span class=\"val\" id=\"aVal\">2</span></label><input type=\"range\" id=\"aSlider\" min=\"2\" max=\"4\" value=\"2\"></div><div class=\"slider-group\"><label>Length L: <span class=\"val\" id=\"lVal\">2</span></label><input type=\"range\" id=\"lSlider\" min=\"1\" max=\"3\" value=\"2\"></div><div class=\"slider-group\"><label>Eval outputs B: <span class=\"val\" id=\"bVal\">2</span></label><input type=\"range\" id=\"bSlider\" min=\"2\" max=\"4\" value=\"2\"></div></div><div class=\"info\" id=\"countBox\"></div></div><div class=\"card\"><h3 style=\"color:#7eb8ff;margin-bottom:8px\">Attempted Encoding Table</h3><p style=\"font-size:.8em;color:#888;margin-bottom:10px\">Each row is a volume. Each column shows what evaluation function that volume would encode. The <span style=\"color:#ff6666\">red diagonal</span> shows where self-reference breaks — we flip each diagonal entry to construct a function that NO volume encodes.</p><div style=\"overflow-x:auto\"><table id=\"diagTable\"></table></div></div><div class=\"card\"><canvas id=\"vizCanvas\" height=\"300\"></canvas><div class=\"info\" id=\"explainBox\"></div></div></div><script>const aS=document.getElementById('aSlider'),lS=document.getElementById('lSlider'),bS=document.getElementById('bSlider'),aV=document.getElementById('aVal'),lV=document.getElementById('lVal'),bV=document.getElementById('bVal'),countBox=document.getElementById('countBox'),diagTable=document.getElementById('diagTable'),vizCanvas=document.getElementById('vizCanvas'),vizCtx=vizCanvas.getContext('2d'),explainBox=document.getElementById('explainBox');function update(){const A=+aS.value,L=+lS.value,B=+bS.value;aV.textContent=A;lV.textContent=L;bV.textContent=B;const nVols=Math.pow(A,L);const nEvals=Math.pow(B,nVols);countBox.innerHTML=`<b>Volumes:</b> A<sup>L</sup> = ${A}<sup>${L}</sup> = <span class=\"highlight\">${nVols}</span><br><b>Evaluation functions:</b> B<sup>A<sup>L</sup></sup> = ${B}<sup>${nVols}</sup> = <span class=\"highlight\">${nEvals}</span><br><b>Ratio:</b> ${(nEvals/nVols).toFixed(1)}× more functions than volumes — <span style=\"color:#ff6666\">encoding is impossible!</span>`;const vols=[];function genVols(prefix){if(prefix.length===L){vols.push([...prefix]);return}for(let a=0;a<A;a++){prefix.push(a);genVols(prefix);prefix.pop()}}genVols([]);const maxShow=Math.min(nVols,16);const maxEvalShow=Math.min(nEvals,16);const evals=[];function genEvals(prefix){if(evals.length>=maxEvalShow)return;if(prefix.length===nVols){evals.push([...prefix]);return}for(let b=0;b<B;b++){prefix.push(b);genEvals(prefix);prefix.pop()}}genEvals([]);let html='<thead><tr><th>Vol \\\\ Eval#</th>';for(let j=0;j<Math.min(maxShow,maxEvalShow);j++)html+=`<th>f<sub>${j}</sub></th>`;html+='<th>diag′</th></tr></thead><tbody>';const diagNew=[];for(let i=0;i<Math.min(maxShow,maxEvalShow);i++){html+=`<tr><td style=\"color:#7eb8ff\">${vols[i].join('')}</td>`;for(let j=0;j<Math.min(maxShow,maxEvalShow);j++){const val=j<evals.length&&i<evals[j].length?evals[j][i]:'?';const isDiag=i===j;html+=`<td class=\"${isDiag?'diag':''}\">${val}</td>`}const diagVal=i<evals.length&&i<evals[i].length?(evals[i][i]+1)%B:'?';diagNew.push(diagVal);html+=`<td style=\"color:#ffcc00;font-weight:bold\">${diagVal}</td></tr>`}html+='</tbody>';diagTable.innerHTML=html;const W=vizCanvas.width=vizCanvas.offsetWidth*2,H=vizCanvas.height=600;vizCtx.clearRect(0,0,W,H);vizCtx.fillStyle='#1a1a3a';vizCtx.fillRect(0,0,W,H);const cx=W/2,cy=H/2;const rVols=Math.min(W,H)*.35;const rEvals=Math.min(W,H)*.2;vizCtx.strokeStyle='#3a3a5a';vizCtx.lineWidth=2;vizCtx.beginPath();vizCtx.arc(cx-W*.18,cy,rVols,0,Math.PI*2);vizCtx.stroke();vizCtx.fillStyle='#7eb8ff';vizCtx.font='bold 24px sans-serif';vizCtx.textAlign='center';vizCtx.fillText(`Volumes (${nVols})`,cx-W*.18,cy-rVols-15);vizCtx.strokeStyle='#5a3a3a';vizCtx.beginPath();vizCtx.arc(cx+W*.18,cy,rEvals*1.5,0,Math.PI*2);vizCtx.stroke();vizCtx.fillStyle='#ff8888';vizCtx.fillText(`Eval Functions (${nEvals>999?'10^'+Math.log10(nEvals).toFixed(1):nEvals})`,cx+W*.18,cy-rEvals*1.5-15);for(let i=0;i<Math.min(maxShow,8);i++){const ang=Math.PI*2*i/Math.min(maxShow,8)-Math.PI/2;const vx=cx-W*.18+rVols*.7*Math.cos(ang);const vy=cy+rVols*.7*Math.sin(ang);vizCtx.beginPath();vizCtx.arc(vx,vy,14,0,Math.PI*2);vizCtx.fillStyle='#7eb8ff';vizCtx.fill();vizCtx.fillStyle='#000';vizCtx.font='bold 16px monospace';vizCtx.fillText(vols[i].join(''),vx,vy+5)}const showArrows=Math.min(maxShow,8,maxEvalShow);for(let i=0;i<showArrows;i++){const ang1=Math.PI*2*i/showArrows-Math.PI/2;const ang2=Math.PI*2*i/Math.min(maxEvalShow,12)-Math.PI/2;const x1=cx-W*.18+rVols*.7*Math.cos(ang1)+18;const y1=cy+rVols*.7*Math.sin(ang1);const x2=cx+W*.18+rEvals*Math.cos(ang2)-14;const y2=cy+rEvals*Math.sin(ang2);vizCtx.beginPath();vizCtx.moveTo(x1,y1);vizCtx.lineTo(x2,y2);vizCtx.strokeStyle='rgba(255,100,100,0.3)';vizCtx.lineWidth=1.5;vizCtx.stroke()}vizCtx.fillStyle='#ff6666';vizCtx.font='bold 28px sans-serif';vizCtx.fillText('✗',cx,cy+rVols+40);vizCtx.fillStyle='#ff6666';vizCtx.font='20px sans-serif';vizCtx.fillText('No surjection possible!',cx,cy+rVols+70);explainBox.innerHTML=`<b>The Diagonal Argument:</b> Suppose we could encode every evaluation function as a volume. Look at the diagonal of the encoding table: volume <i>i</i> encodes function <i>f<sub>i</sub></i>, and <i>f<sub>i</sub>(vol<sub>i</sub>)</i> is the diagonal entry. Now construct a <span class=\"highlight\">new function</span> that differs from <i>f<sub>i</sub></i> at volume <i>i</i> (by adding 1 mod B). This new function <b>cannot equal any <i>f<sub>i</sub></i></b>, so it has no encoding — contradiction!<br><br>This is the <b>No Universal Self-Evaluator Theorem</b>: the Library cannot faithfully catalog itself.`}aS.oninput=update;lS.oninput=update;bS.oninput=update;update()</script></body></html>"
    }
  ]
}

bf32caff-51cb-4fa2-b2fb-959ce2695340.result_lean:
theorem babel_diameter_achieved {A L : ℕ} (hA : 2 ≤ A) (hL : 1 ≤ L) :
    ∃ v w : Volume A L, hammingDist v w = L := by
      refine' ⟨ fun _ => ⟨ 0, by linarith ⟩, fun _ => ⟨ 1, by linarith ⟩, _ ⟩;
      unfold hammingDist; aesop;

/-! ## Volume Cardinality -/


theorem volume_card (A L : ℕ) : Fintype.card (Volume A L) = A ^ L := by
  simp [Fintype.card_fin]

/-! ## Coding-Theoretic Bounds -/

/-
**Singleton Bound**: A code with minimum distance `d` has at most `A^(L - d + 1)` codewords.
-/

theorem hamming_bound {A L : ℕ} (hA : 1 ≤ A) (C : BabelCode A L)
    (t : ℕ) (ht : 2 * t + 1 ≤ C.minDist) (htL : t ≤ L) :
    C.codewords.card * (∑ i ∈ Finset.range (t + 1), L.choose i * (A - 1) ^ i) ≤ A ^ L := by
      -- Each ball has size $\sum_{i=0}^t \binom{L}{i}(A-1)^i$.
      have h_ball_size : ∀ v ∈ C.codewords, (Finset.filter (fun w => hammingDist v w ≤ t) Finset.univ).card = ∑ i ∈ Finset.range (t + 1), Nat.choose L i * (A - 1) ^ i := by
        intro v hv;
        -- For each $i \leq t$, the number of volumes that differ from $v$ in exactly $i$ positions is $\binom{L}{i} (A-1)^i$.
        have h_ball_size_i : ∀ i ≤ t, (Finset.filter (fun w => hammingDist v w = i) (Finset.univ : Finset (Volume A L))).card = Nat.choose L i * (A - 1) ^ i := by
          intro i hi
          have h_ball_size_i : (Finset.filter (fun w => hammingDist v w = i) (Finset.univ : Finset (Volume A L))).card = Finset.sum (Finset.powersetCard i (Finset.univ : Finset (Fin L))) (fun s => (A - 1) ^ i) := by
            have h_ball_size_i : ∀ s : Finset (Fin L), s.card = i → (Finset.filter (fun w => Finset.filter (fun j => v j ≠ w j) Finset.univ = s) (Finset.univ : Finset (Volume A L))).card = (A - 1) ^ i := by
              intro s hs
              have h_ball_size_i : (Finset.filter (fun w => Finset.filter (fun j => v j ≠ w j) Finset.univ = s) (Finset.univ : Finset (Volume A L))).card = Finset.card (Finset.pi s (fun j => Finset.univ.erase (v j))) := by
                refine' Finset.card_bij _ _ _ _;
                use fun a ha j hj => a j;
                · grind +splitIndPred;
                · simp +contextual [ funext_iff, Finset.ext_iff ];
                  grind;
                · intro b hb; use fun j => if hj : j ∈ s then b j hj else v j; simp_all +decide [ Finset.ext_iff ] ;
                  exact fun a => ⟨ fun ⟨ ha, ha' ⟩ => ha, fun ha => ⟨ ha, Ne.symm ( hb a ha ) ⟩ ⟩;
              simp_all +decide [ Finset.card_univ ];
            rw [ ← Finset.sum_congr rfl fun s hs => h_ball_size_i s <| Finset.mem_powersetCard.mp hs |>.2 ];
            rw [ ← Finset.card_biUnion ];
            · congr with w ; simp +decide [ hammingDist ];
            · exact fun s hs t ht hst => Finset.disjoint_left.mpr fun x hx hx' => hst <| by aesop;
          aesop;
        rw [ ← Finset.sum_congr rfl fun i hi => h_ball_size_i i <| Finset.mem_range_succ_iff.mp hi, ← Finset.card_biUnion ];
        · congr with w ; simp +decide [ Nat.lt_succ_iff ];
        · grind +suggestions;
      have h_disjoint_balls : ∀ (v w : Volume A L), v ∈ C.codewords → w ∈ C.codewords → v ≠ w → Disjoint (Finset.filter (fun u => hammingDist v u ≤ t) Finset.univ) (Finset.filter (fun u => hammingDist w u ≤ t) Finset.univ) := by
        intros v w hv hw hvw
        by_contra h_not_disjoint
        obtain ⟨u, hu⟩ : ∃ u, hammingDist v u ≤ t ∧ hammingDist w u ≤ t := by
          exact Exists.elim ( Finset.not_disjoint_iff.mp h_not_disjoint ) fun x hx => ⟨ x, by aesop ⟩;
        have h_triangle : hammingDist v w ≤ hammingDist v u + hammingDist u w := by
          exact Finset.card_le_card ( show Finset.filter ( fun i => v i ≠ w i ) Finset.univ ⊆ Finset.filter ( fun i => v i ≠ u i ) Finset.univ ∪ Finset.filter ( fun i => u i ≠ w i ) Finset.univ from fun i hi => by by_cases hi' : v i = u i <;> aesop ) |> le_trans <| Finset.card_union_le _ _;
        linarith [ C.dist_bound v hv w hw hvw, show hammingDist u w = hammingDist w u from hammingDist_comm u w ];
      have h_sum_ball_size : (Finset.biUnion C.codewords (fun v => Finset.filter (fun u => hammingDist v u ≤ t) Finset.univ)).card = C.codewords.card * (∑ i ∈ Finset.range (t + 1), Nat.choose L i * (A - 1) ^ i) := by
        rw [ Finset.card_biUnion ];
        · rw [ Finset.sum_congr rfl h_ball_size, Finset.sum_const, smul_eq_mul, mul_comm ];
        · exact fun v hv w hw hvw => h_disjoint_balls v w hv hw hvw;
      exact h_sum_ball_size ▸ le_trans ( Finset.card_le_univ _ ) ( by simp +decide [ volume_card ] )

/-! ## Self-Reference and Diagonal Arguments -/

/-- A self-evaluation function assigns a boolean to each volume. -/
abbrev SelfEval (A L : ℕ) := Volume A L → Bool

/-
**Finite Cantor**: More self-evaluations than volumes when `A ≥ 2`.
-/

theorem no_universal_self_evaluator (A L : ℕ) (hA : 2 ≤ A) (hL : 1 ≤ L)
    (encode : SelfEval A L → Volume A L) (decode : Volume A L → SelfEval A L) :
    ∃ f : SelfEval A L, decode (encode f) ≠ f := by
      by_contra! h;
      exact absurd ( Fintype.card_le_of_injective _ ( show Function.Injective encode from fun f₁ f₂ hf ↦ by have := h f₁; have := h f₂; aesop ) ) ( by simpa using self_eval_exceeds_volumes A L hA hL )

/-! ## Pattern Density -/

/-- Volumes containing pattern `p` starting at position `pos`. -/
def volumesWithPatternAt {A L m : ℕ} (p : Fin m → Fin A) (pos : ℕ)
    (hpos : pos + m ≤ L) : Finset (Volume A L) :=
  Finset.univ.filter (fun v =>
    ∀ j : Fin m, v ⟨pos + j.val, by omega⟩ = p j)

/-
**Pattern Density**: Exactly `A^(L-m)` volumes contain pattern `p` at a given position.
-/

theorem pattern_density {A L m : ℕ} (hA : 1 ≤ A) (hm : 1 ≤ m) (hmL : m ≤ L)
    (p : Fin m → Fin A) (pos : ℕ) (hpos : pos + m ≤ L) :
    (volumesWithPatternAt p pos hpos).card = A ^ (L - m) := by
      -- The volumes with the pattern at position `pos` are determined by the `L - m` positions not in the pattern.
      set S := Finset.univ.filter (fun i : Fin L => i.val < pos ∨ i.val ≥ pos + m) with hS_def
      have hS_card : S.card = L - m := by
        rw [ Finset.card_eq_of_bijective ];
        use fun i hi => ⟨ if i < pos then i else i + m, by split_ifs <;> omega ⟩;
        · intro a ha; use if a.val < pos then a.val else a.val - m; split_ifs <;> simp_all +decide [ Fin.ext_iff ] ; omega;
          · omega;
          · exact ⟨ by omega, Nat.sub_add_cancel ( by omega ) ⟩;
        · grind;
        · grind;
      -- The set of volumes with the pattern at position `pos` is in bijection with the set of functions from `S` to `Fin A`.
      have h_bij : volumesWithPatternAt p pos hpos = Finset.image (fun f : S → Fin A => fun i : Fin L => if hi : i ∈ S then f ⟨i, hi⟩ else p ⟨i.val - pos, by
        grind⟩) (Finset.univ : Finset (S → Fin A)) := by
        ext v; simp [volumesWithPatternAt, S];
        constructor;
        · intro hv
          use fun i => v i.val
          funext i
          simp [hv];
          intro hp hq; specialize hv ⟨ i - pos, by omega ⟩ ; aesop;
        · grind
      generalize_proofs at *;
      rw [ h_bij, Finset.card_image_of_injective ];
      · simp +decide [ Finset.card_univ, hS_card ];
      · intro f g hfg; ext i; replace hfg := congr_fun hfg i; aesop;

/-
**Redundancy**: Pattern count times `A^m` equals total Library size.
-/

