      "title": "De Bruijn Catalog Builder",
      "description": "Build and visualize a de Bruijn sequence catalog for a micro-Library. See every possible volume appear as a sliding window in the sequence.",
      "html": "<!DOCTYPE html><html lang='en'><head><meta charset='UTF-8'><title>De Bruijn Catalog Builder</title><style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;justify-content:center;padding:40px}main{max-width:800px;width:100%}h1{text-align:center;font-size:1.8em;margin-bottom:8px;background:linear-gradient(135deg,#06b6d4,#8b5cf6);-webkit-background-clip:text;-webkit-text-fill-color:transparent}p.sub{text-align:center;color:#888;margin-bottom:24px;font-size:.95em}.controls{background:#111827;border-radius:12px;padding:20px;margin-bottom:20px;border:1px solid #1e293b;display:flex;gap:20px;align-items:center;flex-wrap:wrap}.ctrl{display:flex;flex-direction:column;gap:4px}.ctrl label{font-weight:600;color:#67e8f9;font-size:.85em}.ctrl select,.ctrl input{background:#1e293b;border:1px solid #334155;border-radius:6px;padding:6px 10px;color:#e0e0e0;font-size:1em}.ctrl button{background:linear-gradient(135deg,#06b6d4,#8b5cf6);border:none;border-radius:8px;padding:10px 24px;color:white;font-weight:700;cursor:pointer;font-size:1em;margin-top:18px}.ctrl button:hover{opacity:.9}.stats{background:#111827;border-radius:12px;padding:16px 20px;margin-bottom:20px;border:1px solid #1e293b;display:grid;grid-template-columns:repeat(3,1fr);gap:12px;text-align:center}.stat-val{font-size:1.5em;font-weight:700;color:#67e8f9}.stat-lbl{font-size:.8em;color:#888;margin-top:2px}.seq-box{background:#111827;border-radius:12px;padding:20px;margin-bottom:20px;border:1px solid #1e293b}.seq-box h3{color:#67e8f9;margin-bottom:12px;font-size:1em}.seq{font-family:'Courier New',monospace;font-size:1em;word-break:break-all;line-height:1.8;max-height:200px;overflow-y:auto}.seq .hl{background:#8b5cf655;border-radius:3px;padding:1px 0}.slider-row{display:flex;align-items:center;gap:12px;margin-bottom:12px}.slider-row input{flex:1;accent-color:#8b5cf6}.slider-row span{min-width:80px;color:#c4b5fd;font-family:monospace}.window-display{display:flex;gap:3px;justify-content:center;margin:12px 0}.window-display .wc{width:32px;height:40px;display:flex;align-items:center;justify-content:center;border-radius:6px;font-family:'Courier New',monospace;font-weight:700;font-size:1.1em;background:#1e1b4b;color:#c4b5fd;border:2px solid #6366f1}.coverage{background:#111827;border-radius:12px;padding:16px 20px;border:1px solid #1e293b}.coverage h3{color:#67e8f9;margin-bottom:8px;font-size:1em}.cov-grid{display:flex;flex-wrap:wrap;gap:3px;max-height:200px;overflow-y:auto}.cov-item{padding:2px 6px;border-radius:4px;font-family:monospace;font-size:.75em;background:#1e293b;color:#888}.cov-item.found{background:#065f46;color:#6ee7b7}</style></head><body><main><h1>\ud83d\udd17 De Bruijn Catalog Builder</h1><p class='sub'>A single sequence that contains every possible volume as a window</p><div class='controls'><div class='ctrl'><label>Alphabet (A)</label><select id='alphaSelect'><option value='2'>2 (Binary)</option><option value='3'>3 (Ternary)</option><option value='4' selected>4 (DNA-like)</option></select></div><div class='ctrl'><label>Book Length (L)</label><select id='lenSelect'><option value='2'>2</option><option value='3' selected>3</option><option value='4'>4</option><option value='5'>5</option></select></div><div class='ctrl'><button id='buildBtn'>\u2699\ufe0f Build Catalog</button></div></div><div class='stats'><div><div class='stat-val' id='seqLen'>-</div><div class='stat-lbl'>Sequence Length</div></div><div><div class='stat-val' id='totalVols'>-</div><div class='stat-lbl'>Total Volumes (A^L)</div></div><div><div class='stat-val' id='covPct'>-</div><div class='stat-lbl'>Coverage</div></div></div><div class='seq-box'><h3>De Bruijn Sequence</h3><div class='slider-row'><span id='posLabel'>Position: 0</span><input type='range' id='posSlider' min='0' max='0' value='0'></div><div class='window-display' id='windowDisp'></div><div class='seq' id='seqDisplay'>Click \"Build Catalog\" to generate...</div></div><div class='coverage'><h3>Volume Coverage</h3><div class='cov-grid' id='covGrid'></div></div></main><script>const syms='0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';let seq=[],A=4,L=3;function deBruijn(a,l){if(l===1){const s=[];for(let i=0;i<a;i++)s.push(i);return s}const k=a,n=l;const alphabet=Array.from({length:k},(_,i)=>i);const a_arr=new Array(k*n).fill(0);const sequence=[];function db(t,p){if(t>n){if(n%p===0)for(let j=1;j<=p;j++)sequence.push(a_arr[j])}else{a_arr[t]=a_arr[t-p];db(t+1,p);for(let j=a_arr[t-p]+1;j<k;j++){a_arr[t]=j;db(t+1,t)}}}db(1,1);return sequence}function build(){A=parseInt(document.getElementById('alphaSelect').value);L=parseInt(document.getElementById('lenSelect').value);if(Math.pow(A,L)>100000){alert('Too large to visualize (A^L > 100,000). Try smaller parameters.');return}seq=deBruijn(A,L);const total=Math.pow(A,L);document.getElementById('seqLen').textContent=seq.length.toLocaleString();document.getElementById('totalVols').textContent=total.toLocaleString();const ps=document.getElementById('posSlider');ps.max=seq.length-1;ps.value=0;updateDisplay();const seen=new Set();for(let i=0;i<seq.length;i++){const w=[];for(let j=0;j<L;j++)w.push(seq[(i+j)%seq.length]);seen.add(w.join(','))}document.getElementById('covPct').textContent=((seen.size/total)*100).toFixed(0)+'%';const grid=document.getElementById('covGrid');let gh='';const allVols=[];function gen(prefix){if(prefix.length===L){allVols.push([...prefix]);return}for(let c=0;c<A;c++){prefix.push(c);gen(prefix);prefix.pop()}}gen([]);allVols.forEach(v=>{const key=v.join(',');const found=seen.has(key);const label=v.map(c=>syms[c]).join('');gh+=`<div class='cov-item${found?\" found\":\"\"}'>${label}</div>`});grid.innerHTML=gh}function updateDisplay(){const pos=parseInt(document.getElementById('posSlider').value);document.getElementById('posLabel').textContent='Position: '+pos;let html='';for(let i=0;i<seq.length;i++){const c=syms[seq[i]];const inWindow=((i-pos+seq.length)%seq.length)<L;html+=inWindow?`<span class='hl'>${c}</span>`:c}document.getElementById('seqDisplay').innerHTML=html;const wd=document.getElementById('windowDisp');let wh='';for(let j=0;j<L;j++){const idx=(pos+j)%seq.length;wh+=`<div class='wc'>${syms[seq[idx]]}</div>`}wd.innerHTML=wh}document.getElementById('buildBtn').addEventListener('click',build);document.getElementById('posSlider').addEventListener('input',updateDisplay);build()</script></body></html>"
