nt(document.getElementById('rslider').value); document.getElementById('kval').textContent = k; document.getElementById('rval').textContent = maxR; let html = '<table style=\"width: 100%; border-collapse: collapse;\">'; html += '<tr style=\"border-bottom: 2px solid #00d4ff;\"><th style=\"padding: 8px; text-align: left; color: #00d4ff;\">Uniformity r</th><th style=\"padding: 8px; text-align: right; color: #00d4ff;\">Lower Bound Exponent C(k,r)</th><th style=\"padding: 8px; text-align: right; color: #00d4ff;\">Upper Bound (tower)</th><th style=\"padding: 8px; text-align: center; color: #00d4ff;\">Growth Type</th></tr>'; let chartHtml = '<div style=\"display: flex; align-items: flex-end; gap: 4px; height: 200px; padding: 10px;\">'; let maxExp = 0; let exps = []; for (let r = 2; r <= maxR && r <= k; r++) { let ckr = choose(k, r); exps.push({r: r, exp: ckr}); if (ckr > maxExp) maxExp = ckr; } for (let r = 2; r <= maxR && r <= k; r++) { let ckr = choose(k, r); let graphBound = choose(2*k-2, k-1); let upperBound = tower(r - 2, graphBound); let growthType = r === 2 ? 'Exponential' : r === 3 ? 'Double Exp.' : r === 4 ? 'Triple Exp.' : 'Tower(' + (r-2) + ')'; let color = r === 2 ? '#4CAF50' : r === 3 ? '#FF9800' : r === 4 ? '#f44336' : '#9C27B0'; html += '<tr style=\"border-bottom: 1px solid #333;\"><td style=\"padding: 8px; color: ' + color + '; font-weight: bold;\">r = ' + r + '</td><td style=\"padding: 8px; text-align: right;\">' + ckr + '</td><td style=\"padding: 8px; text-align: right;\">' + formatNum(upperBound) + '</td><td style=\"padding: 8px; text-align: center; color: ' + color + ';\">' + growthType + '</td></tr>'; let barHeight = maxExp > 0 ? Math.max(5, (Math.log(ckr + 1) / Math.log(maxExp + 1)) * 180) : 5; chartHtml += '<div style=\"flex: 1; text-align: center;\"><div style=\"background: ' + color + '; height: ' + barHeight + 'px; border-radius: 4px 4px 0 0; display: flex; align-items: flex-start; justify-content: center;\"><span style=\"font-size: 11px; padding: 2px; color: white;\">' + ckr + '</span></div><div style=\"font-size: 12px; color: ' + color + '; margin-top: 4px;\">r=' + r + '</div></div>'; } html += '</table>'; chartHtml += '</div>'; document.getElementById('results').innerHTML = html; document.getElementById('chart').innerHTML = chartHtml; let gapRatio = maxR >= 3 && k >= 3 ? (choose(2*k-4, k-2) / choose(k, 3)).toFixed(1) : 'N/A'; document.getElementById('insight').innerHTML = 'For k=' + k + ': The probabilistic lower bound exponent grows as C(k,r) ∼ k<sup>r</sup>/r!, while the upper bound involves towers of height r−2. ' + (maxR >= 3 ? 'The gap ratio between upper and lower exponents for r=3 is about ' + gapRatio + '×. ' : '') + 'Each increase in uniformity fundamentally changes the growth regime — from exponential to double-exponential to triple-exponential and beyond.'; } update();</script></div>"
