inPath();ctx.moveTo(a.x+nx*off,a.y+ny*off);ctx.quadraticCurveTo(mx,my,b.x+nx*off,b.y+ny*off);const isToPerf=intervals[j].type==='perfect';ctx.strokeStyle=isToPerf?'rgba(255,68,68,0.2)':'rgba(68,170,255,0.15)';ctx.lineWidth=count===12?2:0.8;ctx.stroke();const t=0.7;const ex=(1-t)*(1-t)*(a.x+nx*off)+2*(1-t)*t*mx+t*t*(b.x+nx*off);const ey=(1-t)*(1-t)*(a.y+ny*off)+2*(1-t)*t*my+t*t*(b.y+ny*off);const tax=2*(1-t)*((mx)-(a.x+nx*off))+2*t*((b.x+nx*off)-(mx));const tay=2*(1-t)*((my)-(a.y+ny*off))+2*t*((b.y+ny*off)-(my));const al=Math.atan2(tay,tax);ctx.beginPath();ctx.moveTo(ex,ey);ctx.lineTo(ex-8*Math.cos(al-0.3),ey-8*Math.sin(al-0.3));ctx.moveTo(ex,ey);ctx.lineTo(ex-8*Math.cos(al+0.3),ey-8*Math.sin(al+0.3));ctx.strokeStyle=isToPerf?'rgba(255,68,68,0.35)':'rgba(68,170,255,0.25)';ctx.lineWidth=1.5;ctx.stroke()}}for(let i=0;i<N;i++){const v=intervals[i];const isPerf=v.type==='perfect';const selfLoops=isPerf?1:12;const r=isPerf?28:22;ctx.beginPath();ctx.arc(v.x,v.y,r,0,2*Math.PI);ctx.fillStyle=i===hovered?(isPerf?'rgba(255,68,68,0.4)':'rgba(68,170,255,0.3)'):(isPerf?'rgba(255,68,68,0.15)':'rgba(68,170,255,0.1)');ctx.fill();ctx.strokeStyle=isPerf?'#ff4444':'#44aaff';ctx.lineWidth=isPerf?2.5:1.5;ctx.stroke();ctx.fillStyle='#fff';ctx.font='bold 11px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(v.short,v.x,v.y-6);ctx.font='9px system-ui';ctx.fillStyle='#aaa';ctx.fillText(selfLoops+' loop'+(selfLoops>1?'s':''),v.x,v.y+8);const loopA=-Math.PI/2+(2*Math.PI/N)*intervals.indexOf(v);const lr=18;const lcx=v.x+Math.cos(loopA)*(r+lr);const lcy=v.y+Math.sin(loopA)*(r+lr);ctx.beginPath();ctx.arc(lcx,lcy,lr,0,2*Math.PI);ctx.strokeStyle=isPerf?'rgba(255,68,68,0.3)':'rgba(68,170,255,0.15)';ctx.lineWidth=isPerf?1:selfLoops*0.3;ctx.stroke()}}canvas.addEventListener('mousemove',e=>{const rect=canvas.getBoundingClientRect();const mx=e.clientX-rect.left;const my=e.clientY-rect.top;let found=-1;for(let i=0;i<N;i++){const dx=mx-intervals[i].x,dy=my-intervals[i].y;if(dx*dx+d