      "description": "Animated comparison of self-loops at perfect vs imperfect consonances, showing the 1-vs-12 ratio that is the categorical fingerprint of the parallel-fifths rule.",
      "html": "<!DOCTYPE html><html><head><meta charset='utf-8'><title>Self-Loop Dichotomy</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;padding:30px}.title{font-size:1.5em;font-weight:300;color:#88ccff;margin-bottom:5px}.subtitle{font-size:.85em;color:#888;margin-bottom:30px;text-align:center}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;max-width:900px;width:100%}.cell{background:#111;border-radius:12px;padding:15px;text-align:center;position:relative;overflow:hidden}.cell canvas{display:block;margin:0 auto}.cell-name{font-size:1em;margin-top:8px}.cell-type{font-size:.75em;text-transform:uppercase;letter-spacing:2px;margin-top:2px}.cell-count{font-size:2em;font-weight:700;margin-top:5px}.perfect .cell-type{color:#ff6b6b}.imperfect .cell-type{color:#51cf66}.perfect .cell-count{color:#ff6b6b}.imperfect .cell-count{color:#51cf66}.summary{margin-top:30px;background:#111;border-radius:12px;padding:20px;max-width:900px;width:100%;display:flex;gap:20px;justify-content:center;flex-wrap:wrap}.sum-card{text-align:center;padding:15px 25px}.sum-label{font-size:.75em;color:#888;text-transform:uppercase;letter-spacing:1px}.sum-val{font-size:2.5em;font-weight:200}</style></head><body><div class='title'>The Self-Loop Dichotomy</div><div class='subtitle'>Theorem 3: Perfect consonances admit 1 self-loop • Imperfect consonances admit 12</div><div class='grid' id='grid'></div><div class='summary'><div class='sum-card'><div class='sum-label'>Perfect Consonance Self-Loops</div><div class='sum-val' style='color:#ff6b6b'>1</div></div><div class='sum-card'><div class='sum-label'>Imperfect Consonance Self-Loops</div><div class='sum-val' style='color:#51cf66'>12</div></div><div class='sum-card'><div class='sum-label'>Ratio</div><div class='sum-val' style='color:#88ccff'>1:12</div></div><div class='sum-card'><div class='sum-label'>Incoming VLs (Perfect)</div><div class='sum-val' style='color:#ff6b6b'>61</div></div><div class='sum-card'><div class='sum-label'>Incoming VLs (Imperfect)</div><div class='sum-val' style='color:#51cf66'>72</div></div></div><script>const intervals=[{id:0,name:'Unison',perfect:true,loops:1},{id:3,name:'Minor 3rd',perfect:false,loops:12},{id:4,name:'Major 3rd',perfect:false,loops:12},{id:7,name:'Perfect 5th',perfect:true,loops:1},{id:8,name:'Minor 6th',perfect:false,loops:12},{id:9,name:'Major 6th',perfect:false,loops:12}];const grid=document.getElementById('grid');const canvases=[];intervals.forEach((iv,idx)=>{const cell=document.createElement('div');cell.className='cell '+(iv.perfect?'perfect':'imperfect');const cvs=document.createElement('canvas');cvs.width=200;cvs.height=160;cell.appendChild(cvs);cell.innerHTML+=`<div class='cell-name'>${iv.name}</div><div class='cell-type'>${iv.perfect?'Perfect':'Imperfect'} Consonance</div><div class='cell-count'>${iv.loops} loop${iv.loops>1?'s':''}</div>`;grid.appendChild(cell);canvases.push({canvas:cvs,ctx:cvs.getContext('2d'),iv:iv})});let frame=0;function animate(){frame++;canvases.forEach(({canvas:c,ctx,iv})=>{ctx.clearRect(0,0,200,160);const cx=100,cy=75,r=30;ctx.beginPath();ctx.arc(cx,cy,r,0,Math.PI*2);ctx.fillStyle=iv.perfect?'#2a1a1a':'#1a2a1a';ctx.strokeStyle=iv.perfect?'#ff6b6b':'#51cf66';ctx.lineWidth=2;ctx.fill();ctx.stroke();ctx.fillStyle='#fff';ctx.font='bold 14px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(iv.id+'',cx,cy);for(let i=0;i<iv.loops;i++){const angle=i*Math.PI*2/Math.max(iv.loops,1);const loopR=20+i*2;const phase=frame*0.02+i*0.5;const lx=cx+Math.cos(angle)*(r+5);const ly=cy+Math.sin(angle)*(r+5);const ox=Math.cos(angle)*loopR;const oy=Math.sin(angle)*loopR;const pulse=0.5+0.5*Math.sin(phase);const alpha=0.3+pulse*0.5;ctx.beginPath();ctx.ellipse(lx+ox*0.5,ly+oy*0.5,loopR*0.6,loopR*0.3,angle,0,Math.PI*2);ctx.strokeStyle=iv.perfect?`rgba(255,107,107,${alpha})`:`rgba(81,207,102,${alpha})`;ctx.lineWidth=1.5;ctx.stroke()}});requestAnimationFrame(animate)}animate()</script></body></html>"
    }
  ]
}
